import Link from 'next/link';
import { Dialog } from 'radix-ui';

// asChild merges Radix props onto the child element
// The child must accept ref and spread all props
export function DialogWithLink() {
  return (
    <Dialog.Root>
      {/* asChild makes the Link the actual trigger element */}
      <Dialog.Trigger asChild>
        <Link href="/profile">Open Profile</Link>
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay />
        <Dialog.Content>
          <Dialog.Title>Profile</Dialog.Title>
          <Dialog.Close asChild>
            <button>Close</button>
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

