import * as React from 'react';
import { Dialog } from 'radix-ui';

export function DialogInContainer() {
  const containerRef = React.useRef<HTMLDivElement>(null);

  return (
    <div>
      {/* The container where dialog will render */}
      <div ref={containerRef} id="dialog-container" />

      <Dialog.Root>
        <Dialog.Trigger>Open Dialog</Dialog.Trigger>
        {/* Pass container ref to Portal */}
        <Dialog.Portal container={containerRef.current}>
          <Dialog.Overlay />
          <Dialog.Content>
            <Dialog.Title>Custom Container</Dialog.Title>
            <Dialog.Close>Close</Dialog.Close>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    </div>
  );
}

