import * as React from 'react';
import { Dialog } from 'radix-ui';

export function ControlledDialog() {
  const [open, setOpen] = React.useState(false);

  const handleSave = async () => {
    await saveData();
    setOpen(false); // Programmatically close after save
  };

  return (
    <Dialog.Root open={open} onOpenChange={setOpen}>
      <Dialog.Trigger>Open Settings</Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay />
        <Dialog.Content>
          <Dialog.Title>Settings</Dialog.Title>
          {/* Content */}
          <button onClick={handleSave}>Save & Close</button>
          <Dialog.Close>Cancel</Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

import { Tooltip } from 'radix-ui';

// Wrap your app (or section) with TooltipProvider for shared configuration
// This ensures:
// - Consistent delay across all tooltips
// - When one tooltip is open and you move to another, it opens immediately
export function Layout({ children }) {
  return (
    <Tooltip.Provider delayDuration={300} skipDelayDuration={100}>
      {children}
    </Tooltip.Provider>
  );
}

// Individual tooltips don't need their own delay
export function ButtonWithTip({ label, tip }) {
  return (
    <Tooltip.Root>
      <Tooltip.Trigger asChild>
        <button>{label}</button>
      </Tooltip.Trigger>
      <Tooltip.Portal>
        <Tooltip.Content>{tip}</Tooltip.Content>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

import * as React from 'react';
import { Accordion } from 'radix-ui';

// type="multiple" allows multiple panels open at once
// value is string[] and onValueChange receives string[]
export function MultiAccordion() {
  const [openItems, setOpenItems] = React.useState<string[]>([]);

  return (
    <Accordion.Root
      type="multiple"
      value={openItems}
      onValueChange={setOpenItems}
    >
      <Accordion.Item value="item-1">
        <Accordion.Trigger>Section 1</Accordion.Trigger>
        <Accordion.Content>Content 1</Accordion.Content>
      </Accordion.Item>
      <Accordion.Item value="item-2">
        <Accordion.Trigger>Section 2</Accordion.Trigger>
        <Accordion.Content>Content 2</Accordion.Content>
      </Accordion.Item>
    </Accordion.Root>
  );
}

