import * as React from 'react';
import { Dialog } from 'radix-ui';

// Type a wrapper using the Radix primitive's prop types
type CustomTriggerProps = React.ComponentPropsWithoutRef<typeof Dialog.Trigger> & {
  label: string;
};

const CustomTrigger = React.forwardRef<
  React.ElementRef<typeof Dialog.Trigger>,
  CustomTriggerProps
>(({ label, children, ...props }, ref) => (
  <Dialog.Trigger ref={ref} className="custom-trigger" {...props}>
    {label || children}
  </Dialog.Trigger>
));

CustomTrigger.displayName = 'CustomTrigger';

export { CustomTrigger };

/* Radix UI exposes state via data-* attributes */

/* Target open/closed state on Dialog */
.DialogContent[data-state='open'] {
  animation: contentShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

.DialogContent[data-state='closed'] {
  animation: contentHide 150ms ease-in;
}

/* Accordion open/closed */
.AccordionContent[data-state='open'] {
  animation: slideDown 300ms cubic-bezier(0.87, 0, 0.13, 1);
}

.AccordionContent[data-state='closed'] {
  animation: slideUp 300ms cubic-bezier(0.87, 0, 0.13, 1);
}

/* Switch checked/unchecked */
.SwitchThumb[data-state='checked'] {
  transform: translateX(19px);
}

@keyframes contentShow {
  from { opacity: 0; transform: translate(-50%, -48%) scale(0.96); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

import { VisuallyHidden, Dialog } from 'radix-ui';

// VisuallyHidden renders text visually hidden but accessible to screen readers
// Better than aria-label for complex cases or when text is needed in DOM
export function IconDialog() {
  return (
    <Dialog.Root>
      <Dialog.Trigger>
        <PlusIcon />
